    bindUnit(hit, h.idx, '\u03D5' + (h.idx + 1) + ' — how much of h' + (h.idx + 1) + ' is added into y',
      'Output weight \u03D5' + (h.idx + 1), unitPopup(h.idx));
    if (labeled) {
      var p = ptAlong(h.x, h.y, OXN, CY, 0.42, r * 0.55);
      paramEls.push(mathLabel(labG, '\u03D5', String(h.idx + 1), p[0], p[1], fsW, col(h.idx, C_GREY)));
    }
