<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var nnDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var NW = 1245, NH = 380;
nnDraw.viewbox(0, 0, NW, NH);

var C_ORANGE = '#e0846a', C_GREY = '#a3a3a3', C_TEAL = '#4fc2b4',
    C_DIM = '#dedede', C_BLACK = '#000000';
var SERIF = 'Georgia, "Times New Roman", Times, serif';

var CY = 205, IX = 62, HX = 300, OXN = 545, PB = 645;
var B1 = { x: 48, y: 108, r: 27 };
var B2 = { x: 360, y: 44, r: 27 };

var nnState = { labeled: true, D: 3, selected: null };

/* ---------- small helpers ---------- */
function ptAlong(x1, y1, x2, y2, t, off) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var px = -dy / L, py = dx / L;
  if (py > 0) { px = -px; py = -py; }
  return [x1 + dx * t + px * off, y1 + dy * t + py * off];
}

function mathLabel(parent, base, sub, cx, cy, size, color, halo) {
  var g = parent.group();
  var t1 = g.text(base).font({ family: SERIF, size: size, style: 'italic', leading: 1 }).fill(color);
  var w1 = t1.bbox().width, w2 = 0, t2 = null;
  if (sub !== null && sub !== undefined && sub !== '') {
    t2 = g.text(String(sub)).font({ family: SERIF, size: size * 0.66, style: 'italic', leading: 1 }).fill(color);
    w2 = t2.bbox().width;
  }
  var gap = t2 ? size * 0.05 : 0;
  var total = w1 + w2 + gap;
  t1.center(cx - total / 2 + w1 / 2, cy);
  if (t2) t2.center(cx - total / 2 + w1 + gap + w2 / 2, cy + size * 0.30);
  if (halo !== false) {
    t1.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': size * 0.24, 'stroke-linejoin': 'round' });
    if (t2) t2.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': size * 0.22, 'stroke-linejoin': 'round' });
  }
  return g;
}

/* ---------- panel drawing ---------- */
function drawPanel(ox, isA) {
  var g = nnDraw.group().translate(ox, 0);
  var D = nnState.D;
  var spacing = D > 1 ? Math.min(100, 280 / (D - 1)) : 0;
  var r = D > 1 ? Math.min(32, spacing * 0.44) : 32;
  var sel = nnState.selected;
  var labeled = isA && nnState.labeled;

  var fsNode = Math.max(11, r * 0.66);
  var fsW = Math.max(10, r * 0.48);
  var swC = Math.max(1.6, r * 0.086);
  var ew = Math.max(1.3, r * 0.063);
  var head = Math.max(7.5, r * 0.44);

  var hid = [];
  for (var i = 0; i < D; i++) hid.push({ x: HX, y: CY + (i - (D - 1) / 2) * spacing, idx: i });

  var edgeG = g.group(), nodeG = g.group(), labG = g.group();
  var paramEls = [];

  function col(unit, base) { return (sel === null || unit === sel) ? base : C_DIM; }
  function wid(unit) { return (sel !== null && unit === sel) ? ew * 2.0 : ew; }

  function arrow(x1, y1, x2, y2, rr1, rr2, color, w) {
    var gg = edgeG.group();
    var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
    var ux = dx / L, uy = dy / L;
    var sx = x1 + ux * rr1, sy = y1 + uy * rr1;
    var ex = x2 - ux * (rr2 + 1.5), ey = y2 - uy * (rr2 + 1.5);
    var hl = head * (w > ew ? 1.12 : 1);
    var bx = ex - ux * hl, by = ey - uy * hl;
    gg.line(sx, sy, bx + ux * 1.5, by + uy * 1.5).stroke({ color: color, width: w, linecap: 'butt' });
    var hw = hl * 0.40;
    gg.polygon(ex + ',' + ey + ' ' + (bx - uy * hw) + ',' + (by + ux * hw) + ' ' + (bx + uy * hw) + ',' + (by - ux * hw))
      .fill(color).stroke('none');
    var hit = gg.line(sx, sy, ex, ey).stroke({ color: '#000', width: 15, opacity: 0 });
    return hit;
  }

  function bindUnit(el, idx, tip, ptitle, pbody) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      var now = (nnState.selected === idx) ? null : idx;
      nnState.selected = now;
      hideTooltip();
      render();
      if (now === null) { hidePopup(); } else { showPopup(ptitle, pbody); }
    });
  }

  function unitPopup(i) {
    var n = i + 1;
    return ['Hidden unit h' + n + ' owns exactly three parameters: θ' + n + '0 shifts its line up or down, θ' + n +
      '1 sets how steeply it responds to x, and the ReLU a[·] clips the negative part to zero — that is the teal kink.',
      'The single weight ϕ' + n + ' then decides how much of this kinked line is poured into the output y.'].join(' ');
  }

  /* ---- input -> hidden edges ---- */
  hid.forEach(function (h) {
    var hit = arrow(IX, CY, h.x, h.y, r, r, col(h.idx, C_BLACK), wid(h.idx));
    bindUnit(hit, h.idx, 'θ' + (h.idx + 1) + '1 — slope: how strongly x drives h' + (h.idx + 1),
      'Slope θ' + (h.idx + 1) + '1', unitPopup(h.idx));
    if (labeled) {
      var p = ptAlong(IX, CY, h.x, h.y, 0.38, r * 0.55);
      paramEls.push(mathLabel(labG, '\u03B8', (h.idx + 1) + '1', p[0], p[1], fsW, col(h.idx, C_GREY)));
    }
  });

  /* ---- hidden -> output edges ---- */
  hid.forEach(function (h) {
    var hit = arrow(h.x, h.y, OXN, CY, r, r, col(h.idx, C_BLACK), wid(h.idx));
    bindUnit(hit, h.idx, '\u03D5' + (h.idx + 1) + ' — how much of h' + (h.idx + 1) + ' is added into y',
      'Output weight \u03D5' + (h.idx + 1), unitPopup(h.idx));
    if (labeled) {
      var p = ptAlong(h.x, h.y, OXN, CY, 0.42, r * 0.55);
      paramEls.push(mathLabel(labG, '\u03D5', String(h.idx + 1), p[0], p[1], fsW, col(h.idx, C_GREY)));
    }
  });

  /* ---- bias edges (labeled view only) ---- */
  if (labeled) {
    hid.forEach(function (h) {
      var hit = arrow(B1.x, B1.y, h.x, h.y, B1.r, r, col(h.idx, C_ORANGE), wid(h.idx));
      bindUnit(hit, h.idx, 'θ' + (h.idx + 1) + '0 — bias: shifts h' + (h.idx + 1) + '\u2019s kink left or right',
        'Bias θ' + (h.idx + 1) + '0', unitPopup(h.idx));
      var p = ptAlong(B1.x, B1.y, h.x, h.y, 0.68, r * 0.55);
      paramEls.push(mathLabel(labG, '\u03B8', (h.idx + 1) + '0', p[0], p[1], fsW, col(h.idx, C_ORANGE)));
    });
    var hb = arrow(B2.x, B2.y, OXN, CY, B2.r, r, (sel === null ? C_ORANGE : C_DIM), ew);
    hb.css('cursor', 'pointer');
    hb.on('mousemove', function (e) { showTooltip('\u03D50 — the output bias, added to y no matter what x is', e); });
    hb.on('mouseleave', function () { hideTooltip(); });
    hb.on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      showPopup('Output bias \u03D50',
        'The constant node 1 feeding y contributes ϕ0 regardless of the input. It moves the whole output curve vertically; every other term is a scaled, clipped copy of x.');
    });
    var pb = ptAlong(B2.x, B2.y, OXN, CY, 0.40, r * 0.60);
    paramEls.push(mathLabel(labG, '\u03D5', '0', pb[0], pb[1], fsW, (sel === null ? C_ORANGE : C_DIM)));
  }

  /* ---- nodes ---- */
  var xc = nodeG.circle(r * 2).center(IX, CY).fill('#fff').stroke({ color: C_BLACK, width: swC });
  var xl = mathLabel(labG, 'x', '', IX, CY, fsNode, C_BLACK);
  [xc, xl].forEach(function (el) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip('Input x — one scalar, shared by every hidden unit', e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      showPopup('Input x', 'A single scalar input fans out to all D hidden units. Each unit sees the same x but applies its own slope θi1 and bias θi0, so each builds a different kinked line.');
    });
  });

  hid.forEach(function (h) {
    var dim = (sel !== null && sel !== h.idx);
    var c = nodeG.circle(r * 2).center(h.x, h.y).fill('#fff')
      .stroke({ color: dim ? '#c2c2c2' : C_BLACK, width: (sel === h.idx ? swC * 1.5 : swC) });
    if (labeled) {
      var kp = (h.x - 0.66 * r) + ',' + (h.y + 0.30 * r) + ' ' +
               (h.x - 0.06 * r) + ',' + (h.y + 0.30 * r) + ' ' +
               (h.x + 0.52 * r) + ',' + (h.y - 0.36 * r);
      var k = nodeG.polyline(kp).fill('none')
        .stroke({ color: dim ? '#d6ecea' : C_TEAL, width: Math.max(2, r * 0.115), linecap: 'butt', linejoin: 'miter' });
      if (dim) { } else { paramEls.push(k); }
    }
    var lb = mathLabel(labG, 'h', String(h.idx + 1), h.x + r * 0.13, h.y - r * 0.02, fsNode, dim ? '#909090' : C_BLACK);
    bindUnit(c, h.idx, 'h' + (h.idx + 1) + ' = a[θ' + (h.idx + 1) + '0 + θ' + (h.idx + 1) + '1 x]  — click to trace it',
      'Hidden unit h' + (h.idx + 1), unitPopup(h.idx));
    bindUnit(lb, h.idx, 'h' + (h.idx + 1) + ' = a[θ' + (h.idx + 1) + '0 + θ' + (h.idx + 1) + '1 x]  — click to trace it',
      'Hidden unit h' + (h.idx + 1), unitPopup(h.idx));
  });

  var yc = nodeG.circle(r * 2).center(OXN, CY).fill('#fff').stroke({ color: C_BLACK, width: swC });
  var yl = mathLabel(labG, 'y', '', OXN, CY, fsNode, C_BLACK);
  [yc, yl].forEach(function (el) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip('Output y = \u03D50 + \u03A3 \u03D5i hi', e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      showPopup('Output y', 'The output is a weighted sum of the hidden activations plus a bias: y = ϕ0 + Σ ϕi hi. Because every hi is a clipped straight line, y is a piecewise-linear function with one kink per hidden unit.');
    });
  });

  /* ---- bias nodes ---- */
  if (labeled) {
    var b1c = nodeG.circle(B1.r * 2).center(B1.x, B1.y).fill('#fff')
      .stroke({ color: (sel === null ? C_ORANGE : '#f0cdc1'), width: swC });
    var b1l = mathLabel(labG, '1', '', B1.x, B1.y, fsNode, (sel === null ? C_ORANGE : '#efc8bb'));
    var b2c = nodeG.circle(B2.r * 2).center(B2.x, B2.y).fill('#fff')
      .stroke({ color: (sel === null ? C_ORANGE : '#f0cdc1'), width: swC });
    var b2l = mathLabel(labG, '1', '', B2.x, B2.y, fsNode, (sel === null ? C_ORANGE : '#efc8bb'));
    paramEls.push(b1c, b1l, b2c, b2l);
    [[b1c, 'Constant 1 — turns θi0 into each hidden unit\u2019s bias'],
     [b1l, 'Constant 1 — turns θi0 into each hidden unit\u2019s bias'],
     [b2c, 'Constant 1 — turns \u03D50 into the output bias'],
     [b2l, 'Constant 1 — turns \u03D50 into the output bias']].forEach(function (pair) {
      pair[0].css('cursor', 'pointer');
      pair[0].on('mousemove', function (e) { showTooltip(pair[1], e); });
      pair[0].on('mouseleave', function () { hideTooltip(); });
      pair[0].on('click', function (e) {
        if (e && e.stopPropagation) e.stopPropagation();
        showPopup('Bias node "1"', 'Drawing a node that always outputs 1 lets a bias be treated as just another weight on just another edge. θi0 and ϕ0 are the weights on those constant edges.');
      });
    });
  }

  return paramEls;
}

/* ---------- render ---------- */
function render(opts) {
  nnDraw.clear();
  var bg = nnDraw.rect(NW, NH).fill('#ffffff');
  bg.on('click', function () {
    if (nnState.selected !== null) { nnState.selected = null; hidePopup(); render(); }
  });

  var paramEls = drawPanel(0, true);
  drawPanel(PB, false);

  nnDraw.text('a)').font({ family: 'Arial, Helvetica, sans-serif', size: 26, leading: 1 }).fill('#000').move(10, 12);
  nnDraw.text('b)').font({ family: 'Arial, Helvetica, sans-serif', size: 26, leading: 1 }).fill('#000').move(PB + 10, 12);

  if (opts && opts.pulse) {
    paramEls.forEach(function (el) {
      el.attr('opacity', 0.06);
      el.animate(750).attr({ opacity: 1 });
    });
  }
}

/* ---------- controls ---------- */
function toggle_labelView(on) {
  nnState.labeled = !!on;
  render();
}
function update_hiddenCount(v) {
  nnState.D = v;
  if (nnState.selected !== null && nnState.selected >= v) nnState.selected = null;
  render();
}
function trigger_clearSelection() {
  nnState.selected = null;
  hidePopup();
  render();
}

/* ---------- demo steps ---------- */
var nnSteps = [
  {
    title: 'The bare network',
    narr: 'One input x fans out to three hidden units, which all feed a single output y. Panel b (right) shows that bare architecture; panel a (left) is the identical network with every parameter named.',
    st: { labeled: true, D: 3, sel: null }, pulse: false
  },
  {
    title: 'Name every parameter',
    narr: 'The labeled view adds the two orange bias nodes and every weight name: \u03B8i0 and \u03B8i1 on the input side, \u03D50 and \u03D5i on the output side. Untick "Fully labeled" to see that the topology is unchanged.',
    st: { labeled: true, D: 3, sel: null }, pulse: true
  },
  {
    title: 'Follow one hidden unit',
    narr: 'h2 is highlighted: its incoming pair \u03B820 (bias) and \u03B821 (slope from x) form the pre-activation, the teal kink applies the ReLU, and \u03D52 scales its contribution to y. Click any other hi to trace it.',
    st: { labeled: true, D: 3, sel: 1 }, pulse: false
  },
  {
    title: 'Grow the hidden layer',
    narr: 'With D = 6 each new unit brings its own \u03B8i0, \u03B8i1 and \u03D5i, so the parameter count grows as 3D + 1 while the input and output stay single nodes.',
    st: { labeled: true, D: 6, sel: null }, pulse: false
  },
  {
    title: 'Shrink to one unit',
    narr: 'With D = 1 the network collapses to a single kinked line: y = \u03D50 + \u03D51\u00B7a[\u03B810 + \u03B811 x]. Everything richer is just a sum of more such pieces.',
    st: { labeled: true, D: 1, sel: null }, pulse: false
  }
];
var nnStep = 0;

function applyStep(i) {
  nnStep = (i % nnSteps.length + nnSteps.length) % nnSteps.length;
  var s = nnSteps[nnStep];
  nnState.labeled = s.st.labeled;
  nnState.D = s.st.D;
  nnState.selected = s.st.sel;
  document.getElementById('labelViewInput').checked = nnState.labeled;
  document.getElementById('hiddenCountInput').value = nnState.D;
  document.getElementById('hiddenCountVal').value = nnState.D;
  document.getElementById('demoNarration').innerHTML = '<strong>' + s.title + '.</strong> ' + s.narr;
  document.getElementById('stepLabel').textContent = 'Step ' + (nnStep + 1) + ' / ' + nnSteps.length;
  hidePopup();
  render({ pulse: s.pulse });
}
function nextStep() { applyStep(nnStep + 1); }
function prevStep() { applyStep(nnStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

