var SERIF = 'Georgia, "Times New Roman", Times, serif';
var SANS = 'Arial, Helvetica, sans-serif';

/* ---------- panel-local geometry (panel width 620) ---------- */
var PW = 620, CY = 208, IX = 46, HX = 306, OX = 574;
var B1X = 40, B1Y = 104, B2X = 300, B2Y = 38;
var MAXSPAN = 230, MAXSPACING = 92, RMAX = 32;

var nnState = { labeled: true, D: 3, selected: null };
var cSize = { w: 0, h: 0 };

(function initSize() {
  var c = document.getElementById('container');
  var st = getComputedStyle(c);
  cSize.w = Math.max(0, c.clientWidth - (parseFloat(st.paddingLeft) || 0) - (parseFloat(st.paddingRight) || 0));
  cSize.h = Math.max(0, c.clientHeight - (parseFloat(st.paddingTop) || 0) - (parseFloat(st.paddingBottom) || 0));
