function geom() {
  var D = nnState.D;
  var spacing = D > 1 ? Math.min(MAXSPACING, MAXSPAN / (D - 1)) : 0;
  var r = D > 1 ? Math.max(16, Math.min(RMAX, spacing * 0.46)) : RMAX;
  var rB = Math.min(30, Math.max(20, r));
  var half = spacing * (D - 1) / 2;
  return { D: D, spacing: spacing, r: r, rB: rB, half: half,
           top: CY - half - r, bottom: CY + half + r };
}

/* ---------- helpers ---------- */
function ptAlong(x1, y1, x2, y2, t, off) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var px = -dy / L, py = dx / L;
  if (py > 0) { px = -px; py = -py; }
  return [x1 + dx * t + px * off, y1 + dy * t + py * off];
}

function mathLabel(parent, base, sub, cx, cy, size, color) {
  var g = parent.group();
  var t1 = g.text(base).font({ family: SERIF, size: size, style: 'italic', leading: 1 }).fill(color);
  var w1 = t1.bbox().width, w2 = 0, t2 = null;
  if (sub !== null && sub !== undefined && sub !== '') {
    t2 = g.text(String(sub)).font({ family: SERIF, size: size * 0.64, style: 'italic', leading: 1 }).fill(color);
    w2 = t2.bbox().width;
  }
  var gap = t2 ? size * 0.05 : 0;
  var total = w1 + w2 + gap;
  t1.center(cx - total / 2 + w1 / 2, cy);
  if (t2) t2.center(cx - total / 2 + w1 + gap + w2 / 2, cy + size * 0.32);
  t1.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': size * 0.30, 'stroke-linejoin': 'round' });
  if (t2) t2.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': size * 0.28, 'stroke-linejoin': 'round' });
  return g;
}

