    var b1l = mathLabel(labG, '1', '', B1X, B1Y, fsNode, oc);
    var b2c = nodeG.circle(rB * 2).center(B2X, B2Y).fill('#fff').stroke({ color: oc, width: swC });
    var b2l = mathLabel(labG, '1', '', B2X, B2Y, fsNode, oc);
    paramEls.push(b1c, b1l, b2c, b2l);
    [[b1c, 'Constant 1 — turns \u03B8i0 into each hidden unit\u2019s bias'],
     [b1l, 'Constant 1 — turns \u03B8i0 into each hidden unit\u2019s bias'],
     [b2c, 'Constant 1 — turns \u03D50 into the output bias'],
     [b2l, 'Constant 1 — turns \u03D50 into the output bias']].forEach(function (pair) {
      pair[0].css('cursor', 'pointer');
      pair[0].on('mousemove', function (e) { showTooltip(pair[1], e); });
      pair[0].on('mouseleave', function () { hideTooltip(); });
      pair[0].on('click', function (e) {
        if (e && e.stopPropagation) e.stopPropagation();
        showPopup('Bias node "1"', 'Drawing a node that always outputs 1 lets a bias be treated as just another weight on just another edge. \u03B8i0 and \u03D50 are the weights on those constant edges.');
      });
    });
  }

  /* panel letter */
  g.text(letter).font({ family: SANS, size: 30, leading: 1 }).fill('#000').move(2, letterY);

  return paramEls;
}

/* ---------- layout ---------- */
function computeLayout() {
  var G = geom();
  var aspect = (cSize.w > 0 && cSize.h > 0) ? (cSize.w / cSize.h) : 2.0;
  if (aspect >= 2.6) {
    var NH = Math.max(G.bottom, B2Y) + 18;
    return { mode: 'side', NW: PW * 2 + 44, NH: NH,
             offs: [[0, 0], [PW + 44, 0]], letterY: [2, 2] };
  }
  var dyB = (G.bottom + 26) - G.top;
  var NHs = dyB + G.bottom + 18;
  return { mode: 'stack', NW: PW, NH: NHs,
           offs: [[0, 0], [0, dyB]], letterY: [2, Math.max(2, G.top - 40)] };
}

/* ---------- render ---------- */
function render(opts) {
  nnDraw.clear();
  var L = computeLayout();
  nnDraw.viewbox(0, 0, L.NW, L.NH);
  var bg = nnDraw.rect(L.NW, L.NH).fill('#ffffff');
  bg.on('click', function () {
    if (nnState.selected !== null) { nnState.selected = null; hidePopup(); render(); }
  });

  var paramEls = drawPanel(nnDraw, L.offs[0][0], L.offs[0][1], true, 'a)', L.letterY[0]);
  drawPanel(nnDraw, L.offs[1][0], L.offs[1][1], false, 'b)', L.letterY[1]);

  if (opts && opts.pulse) {
    paramEls.forEach(function (el) {
      el.attr('opacity', 0.06);
      el.animate(750).attr({ opacity: 1 });
    });
  }
}

document.addEventListener('fig-resize', function (e) {
  cSize.w = e.detail.width || cSize.w;
  cSize.h = e.detail.height || cSize.h;
  render();
});

/* ---------- controls ---------- */
function toggle_labelView(on) { nnState.labeled = !!on; render(); }
function update_hiddenCount(v) {
  nnState.D = v;
  if (nnState.selected !== null && nnState.selected >= v) nnState.selected = null;
  render();
}
function trigger_clearSelection() { nnState.selected = null; hidePopup(); render(); }

/* ---------- demo steps ---------- */
var nnSteps = [
  { title: 'The bare network',
    narr: 'One input x fans out to three hidden units, which all feed a single output y. Panel b is that bare architecture; panel a is the identical network with every parameter named.',
    st: { labeled: true, D: 3, sel: null }, pulse: false },
  { title: 'Name every parameter',
    narr: 'The labeled view adds the two orange bias nodes and every weight name: \u03B8i0 and \u03B8i1 on the input side, \u03D50 and \u03D5i on the output side. Untick "Fully labeled" to see that the topology is unchanged.',
    st: { labeled: true, D: 3, sel: null }, pulse: true },
  { title: 'Follow one hidden unit',
    narr: 'h2 is highlighted: its incoming pair \u03B820 (bias) and \u03B821 (slope from x) form the pre-activation, the teal kink applies the ReLU, and \u03D52 scales its contribution to y. Click any other hi to trace it.',
    st: { labeled: true, D: 3, sel: 1 }, pulse: false },
  { title: 'Grow the hidden layer',
    narr: 'With D = 6 each new unit brings its own \u03B8i0, \u03B8i1 and \u03D5i, so the parameter count grows as 3D + 1 while the input and output stay single nodes.',
    st: { labeled: true, D: 6, sel: null }, pulse: false },
  { title: 'Shrink to one unit',
    narr: 'With D = 1 the network collapses to a single kinked line: y = \u03D50 + \u03D51\u00B7a[\u03B810 + \u03B811 x]. Everything richer is just a sum of more such pieces.',
    st: { labeled: true, D: 1, sel: null }, pulse: false }
];
var nnStep = 0;

function applyStep(i) {
  nnStep = (i % nnSteps.length + nnSteps.length) % nnSteps.length;
  var s = nnSteps[nnStep];
  nnState.labeled = s.st.labeled;
  nnState.D = s.st.D;
  nnState.selected = s.st.sel;
  document.getElementById('labelViewInput').checked = nnState.labeled;
  document.getElementById('hiddenCountInput').value = nnState.D;
  document.getElementById('hiddenCountVal').value = nnState.D;
  document.getElementById('demoNarration').innerHTML = '<strong>' + s.title + '.</strong> ' + s.narr;
  document.getElementById('stepLabel').textContent = 'Step ' + (nnStep + 1) + ' / ' + nnSteps.length;
  hidePopup();
  render({ pulse: s.pulse });
}
function nextStep() { applyStep(nnStep + 1); }
function prevStep() { applyStep(nnStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: A shallow neural network is a single input fed through D hidden units — each hidden unit applies its own weighted-plus-bias linear function (θ) before a ReLU, and the output is a weighted-plus-bias combination (φ) of those hidden activations.
KEY INSIGHT (what students should walk away understanding): A shallow network is nothing more than D independent copies of 'scale-and-shift x, clip it, then scale again' — the θ's build each hidden unit's kinked line and the φ's decide how much of each line to add into the output.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
