Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<strong style="font-size:12px">Shallow network: θ builds each unit, ϕ mixes them</strong>
<p id="demoNarration" style="margin:0;font-size:12px;line-height:1.45;min-height:92px"></p>
<span style="display:flex;gap:6px;align-items:center;">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;flex:1;text-align:center;color:#444"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label><input id="labelViewInput" type="checkbox" checked onchange="toggle_labelView(this.checked)"> Fully labeled (panel a) &nbsp;<span style="color:#888">— uncheck to make panel a clean like b</span></label>
<label>Number of hidden units D: <output id="hiddenCountVal">3</output>
  <input id="hiddenCountInput" type="range" min="1" max="6" step="1" value="3" oninput="document.getElementById('hiddenCountVal').value=this.value;update_hiddenCount(+this.value)">
</label>
<button onclick="trigger_clearSelection()">Clear unit highlight</button>
<span style="font-size:11px;color:#555">Click any h<sub>i</sub> circle (or one of its arrows) to trace a single hidden unit through the network. Hover any arrow to see what its weight does.</span>
<span style="font-size:11px;color:#222;border-top:1px solid #dcdfe3;padding-top:6px;line-height:1.7">
h<sub>i</sub> = a[ θ<sub>i0</sub> + θ<sub>i1</sub>·x ]<br>
y = ϕ<sub>0</sub> + ϕ<sub>1</sub>h<sub>1</sub> + … + ϕ<sub>D</sub>h<sub>D</sub><br>
<span style="color:#777">parameters = 3D + 1</span>
</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var nnDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');

var C_ORANGE = '#e0846a', C_ORANGE_DIM = '#f3d6cd', C_GREY = '#9d9d9d',
    C_TEAL = '#4fc2b4', C_TEAL_DIM = '#dbeeeb', C_DIM = '#dadada', C_BLACK = '#000000';
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var SANS = 'Arial, Helvetica, sans-serif';

/* ---- panel-local geometry (matches the source proportions) ---- */
var PW = 790, CY = 280, IX = 58, HX = 400, OX = 742;
var B1X = 52, B1Y = 158, B2X = 396, B2Y0 = 58;
var R0 = 42, GAP = 74;

var nnState = { labeled: true, D: 3, selected: null };
var cSize = { w: 0, h: 0 };

(function initSize() {
  var c = document.getElementById('container');
  var st = getComputedStyle(c);
  cSize.w = Math.max(0, c.clientWidth - (parseFloat(st.paddingLeft) || 0) - (parseFloat(st.paddingRight) || 0));
  cSize.h = Math.max(0, c.clientHeight - (parseFloat(st.paddingTop) || 0) - (parseFloat(st.paddingBottom) || 0));
})();

function geom() {
  var D = nnState.D;
  var spacing = D > 1 ? Math.min(103, 400 / (D - 1)) : 0;
  var r = D > 1 ? Math.min(R0, Math.max(22, spacing * 0.42)) : R0;
  var rB = Math.max(24, Math.min(40, r * 0.96));
  var half = spacing * (D - 1) / 2;
  var top = CY - half - r, bottom = CY + half + r;
  var b2y = Math.min(B2Y0, top - rB - 26);
  var topMost = Math.min(b2y - rB, top);
  var shiftY = 14 - topMost;
  var panelH = bottom + shiftY + 26;
  return { D: D, spacing: spacing, r: r, rB: rB, half: half, top: top,
           bottom: bottom, b2y: b2y, shiftY: shiftY, panelH: panelH };
}

/* ---- helpers ---- */
function ptAlong(x1, y1, x2, y2, t, off) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
  var px = -dy / L, py = dx / L;
  if (py > 0) { px = -px; py = -py; }
  return [x1 + dx * t + px * off, y1 + dy * t + py * off];
}

function mathLabel(parent, base, sub, cx, cy, size, color) {
  var g = parent.group();
  var t1 = g.text(base).font({ family: SERIF, size: size, style: 'italic', leading: 1 }).fill(color);
  var w1 = t1.bbox().width, w2 = 0, t2 = null;
  if (sub !== null && sub !== undefined && sub !== '') {
    t2 = g.text(String(sub)).font({ family: SERIF, size: size * 0.66, style: 'italic', leading: 1 }).fill(color);
    w2 = t2.bbox().width;
  }
  var gap = t2 ? size * 0.04 : 0;
  var total = w1 + w2 + gap;
  t1.center(cx - total / 2 + w1 / 2, cy);
  if (t2) t2.center(cx - total / 2 + w1 + gap + w2 / 2, cy + size * 0.33);
  t1.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': size * 0.32, 'stroke-linejoin': 'round' });
  if (t2) t2.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': size * 0.30, 'stroke-linejoin': 'round' });
  return g;
}

/* ---- one panel ---- */
function drawPanel(root, ox, oy, isA, letter) {
  var outer = root.group().translate(ox, oy);
  var G = geom(), D = G.D, r = G.r, rB = G.rB, B2Y = G.b2y;
  var g = outer.group().translate(0, G.shiftY);
  var sel = nnState.selected;
  var labeled = isA && nnState.labeled;

  var fsNode = r * 0.98;
  var fsW = Math.max(16, Math.min(r * 0.70, (G.spacing || 103) * 0.36));
  var swC = Math.max(2, r * 0.085);
  var ew = Math.max(1.8, r * 0.085);
  var hl = r * 0.62, hw = r * 0.26;

  var hid = [];
  for (var i = 0; i < D; i++) hid.push({ x: HX, y: CY + (i - (D - 1) / 2) * G.spacing, idx: i });

  var edgeG = g.group(), nodeG = g.group(), labG = g.group();
  var paramEls = [];

  function col(unit, base) { return (sel === null || unit === sel) ? base : C_DIM; }
  function wid(unit) { return (sel !== null && unit === sel) ? ew * 2.1 : ew; }

  function arrow(x1, y1, x2, y2, rr1, rr2, color, w) {
    var gg = edgeG.group();
    var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy) || 1;
    var ux = dx / L, uy = dy / L;
    var sx = x1 + ux * rr1, sy = y1 + uy * rr1;
    var ex = x2 - ux * (rr2 + 1.2), ey = y2 - uy * (rr2 + 1.2);
    var L2 = hl * (w > ew ? 1.1 : 1), W2 = hw * (w > ew ? 1.1 : 1);
    var bx = ex - ux * L2, by = ey - uy * L2;
    gg.line(sx, sy, bx + ux * 1.2, by + uy * 1.2).stroke({ color: color, width: w, linecap: 'butt' });
    gg.polygon(ex + ',' + ey + ' ' + (bx - uy * W2) + ',' + (by + ux * W2) + ' ' + (bx + uy * W2) + ',' + (by - ux * W2))
      .fill(color).stroke('none');
    return gg.line(sx, sy, ex, ey).stroke({ color: '#000', width: Math.max(12, r * 0.50), opacity: 0 });
  }

  function unitPopup(i) {
    var n = i + 1;
    return 'Hidden unit h' + n + ' owns exactly three parameters: \u03B8' + n + '0 shifts its line up or down, \u03B8' + n +
      '1 sets how steeply it responds to x, and the ReLU a[\u00B7] clips the negative part to zero \u2014 that is the teal kink. ' +
      'The single weight \u03D5' + n + ' then decides how much of this kinked line is poured into the output y.';
  }

  function bindUnit(el, idx, tip, ptitle, pbody) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      var now = (nnState.selected === idx) ? null : idx;
      nnState.selected = now;
      hideTooltip();
      render();
      if (now === null) { hidePopup(); } else { showPopup(ptitle, pbody); }
    });
  }

  /* input -> hidden (black) */
  hid.forEach(function (h) {
    var hit = arrow(IX, CY, h.x, h.y, r, r, col(h.idx, C_BLACK), wid(h.idx));
    bindUnit(hit, h.idx, '\u03B8' + (h.idx + 1) + '1 \u2014 slope: how strongly x drives h' + (h.idx + 1),
      'Slope \u03B8' + (h.idx + 1) + '1', unitPopup(h.idx));
    if (labeled) {
      var p = ptAlong(IX, CY, h.x, h.y, 0.34, r * 0.55);
      paramEls.push(mathLabel(labG, '\u03B8', (h.idx + 1) + '1', p[0], p[1], fsW, col(h.idx, C_GREY)));
    }
  });

  /* hidden -> output (black) */
  hid.forEach(function (h) {
    var hit = arrow(h.x, h.y, OX, CY, r, r, col(h.idx, C_BLACK), wid(h.idx));
    bindUnit(hit, h.idx, '\u03D5' + (h.idx + 1) + ' \u2014 how much of h' + (h.idx + 1) + ' is added into y',
      'Output weight \u03D5' + (h.idx + 1), unitPopup(h.idx));
    if (labeled) {
      var p = ptAlong(h.x, h.y, OX, CY, 0.42, r * 0.58);
      paramEls.push(mathLabel(labG, '\u03D5', String(h.idx + 1), p[0], p[1], fsW, col(h.idx, C_GREY)));
    }
  });

  /* bias edges (orange) */
  if (labeled) {
    hid.forEach(function (h) {
      var hit = arrow(B1X, B1Y, h.x, h.y, rB, r, col(h.idx, C_ORANGE), wid(h.idx));
      bindUnit(hit, h.idx, '\u03B8' + (h.idx + 1) + '0 \u2014 bias: shifts h' + (h.idx + 1) + '\u2019s kink left or right',
        'Bias \u03B8' + (h.idx + 1) + '0', unitPopup(h.idx));
      var tt = (h.y < CY - 1) ? 0.64 : (h.y > CY + 1 ? 0.55 : 0.60);
      var p = ptAlong(B1X, B1Y, h.x, h.y, tt, r * 0.58);
      paramEls.push(mathLabel(labG, '\u03B8', (h.idx + 1) + '0', p[0], p[1], fsW, col(h.idx, C_ORANGE)));
    });
    var hb = arrow(B2X, B2Y, OX, CY, rB, r, (sel === null ? C_ORANGE : C_DIM), ew);
    hb.css('cursor', 'pointer');
    hb.on('mousemove', function (e) { showTooltip('\u03D50 \u2014 the output bias, added to y no matter what x is', e); });
    hb.on('mouseleave', function () { hideTooltip(); });
    hb.on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      showPopup('Output bias \u03D50',
        'The constant node 1 feeding y contributes \u03D50 regardless of the input. It moves the whole output curve vertically; every other term is a scaled, clipped copy of x.');
    });
    var pb = ptAlong(B2X, B2Y, OX, CY, 0.40, r * 0.62);
    paramEls.push(mathLabel(labG, '\u03D5', '0', pb[0], pb[1], fsW, (sel === null ? C_ORANGE : C_ORANGE_DIM)));
  }

  /* input node */
  var xc = nodeG.circle(r * 2).center(IX, CY).fill('#fff').stroke({ color: C_BLACK, width: swC });
  var xl = mathLabel(labG, 'x', '', IX, CY, fsNode, C_BLACK);
  [xc, xl].forEach(function (el) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip('Input x \u2014 one scalar, shared by every hidden unit', e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      showPopup('Input x', 'A single scalar input fans out to all D hidden units. Each unit sees the same x but applies its own slope \u03B8i1 and bias \u03B8i0, so each builds a different kinked line.');
    });
  });

  /* hidden nodes */
  hid.forEach(function (h) {
    var dim = (sel !== null && sel !== h.idx);
    var c = nodeG.circle(r * 2).center(h.x, h.y).fill('#fff')
      .stroke({ color: dim ? '#c9c9c9' : C_BLACK, width: (sel === h.idx ? swC * 1.6 : swC) });
    if (labeled) {
      var kp = (h.x - 0.92 * r) + ',' + (h.y + 0.22 * r) + ' ' +
               (h.x - 0.30 * r) + ',' + (h.y + 0.22 * r) + ' ' +
               (h.x + 0.16 * r) + ',' + (h.y - 0.44 * r);
      var k = nodeG.polyline(kp).fill('none')
        .stroke({ color: dim ? C_TEAL_DIM : C_TEAL, width: Math.max(3, r * 0.20), linecap: 'butt', linejoin: 'miter' });
      k.css('cursor', 'pointer');
      k.on('mousemove', function (e) { showTooltip('ReLU a[\u00B7]: negative pre-activations are clipped to zero \u2014 the kink', e); });
      k.on('mouseleave', function () { hideTooltip(); });
      if (!dim) paramEls.push(k);
    }
    var lx = labeled ? h.x + r * 0.32 : h.x + r * 0.05;
    var lb = mathLabel(labG, 'h', String(h.idx + 1), lx, h.y - r * 0.03, fsNode, dim ? '#9a9a9a' : C_BLACK);
    var tip = 'h' + (h.idx + 1) + ' = a[\u03B8' + (h.idx + 1) + '0 + \u03B8' + (h.idx + 1) + '1 x]  \u2014 click to trace it';
    bindUnit(c, h.idx, tip, 'Hidden unit h' + (h.idx + 1), unitPopup(h.idx));
    bindUnit(lb, h.idx, tip, 'Hidden unit h' + (h.idx + 1), unitPopup(h.idx));
  });

  /* output node */
  var yc = nodeG.circle(r * 2).center(OX, CY).fill('#fff').stroke({ color: C_BLACK, width: swC });
  var yl = mathLabel(labG, 'y', '', OX, CY, fsNode, C_BLACK);
  [yc, yl].forEach(function (el) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip('Output y = \u03D50 + \u03A3 \u03D5i hi', e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      showPopup('Output y', 'The output is a weighted sum of the hidden activations plus a bias: y = \u03D50 + \u03A3 \u03D5i hi. Because every hi is a clipped straight line, y is a piecewise-linear function with one kink per hidden unit.');
    });
  });

  /* bias nodes */
  if (labeled) {
    var oc = (sel === null ? C_ORANGE : C_ORANGE_DIM);
    var b1c = nodeG.circle(rB * 2).center(B1X, B1Y).fill('#fff').stroke({ color: oc, width: swC });
    var b1l = mathLabel(labG, '1', '', B1X, B1Y, fsNode, oc);
    var b2c = nodeG.circle(rB * 2).center(B2X, B2Y).fill('#fff').stroke({ color: oc, width: swC });
    var b2l = mathLabel(labG, '1', '', B2X, B2Y, fsNode, oc);
    paramEls.push(b1c, b1l, b2c, b2l);
    [[b1c, 'Constant 1 \u2014 turns \u03B8i0 into each hidden unit\u2019s bias'],
     [b1l, 'Constant 1 \u2014 turns \u03B8i0 into each hidden unit\u2019s bias'],
     [b2c, 'Constant 1 \u2014 turns \u03D50 into the output bias'],
     [b2l, 'Constant 1 \u2014 turns \u03D50 into the output bias']].forEach(function (pair) {
      pair[0].css('cursor', 'pointer');
      pair[0].on('mousemove', function (e) { showTooltip(pair[1], e); });
      pair[0].on('mouseleave', function () { hideTooltip(); });
      pair[0].on('click', function (e) {
        if (e && e.stopPropagation) e.stopPropagation();
        showPopup('Bias node "1"', 'Drawing a node that always outputs 1 lets a bias be treated as just another weight on just another edge. \u03B8i0 and \u03D50 are the weights on those constant edges.');
      });
    });
  }

  /* panel letter (outside the vertical shift so it stays at the top) */
  outer.text(letter).font({ family: SANS, size: 36, leading: 1 }).fill('#000').move(4, 2);

  return paramEls;
}

/* ---- layout: side-by-side panels like the source ---- */
function computeLayout() {
  var G = geom();
  var aspect = (cSize.w > 0 && cSize.h > 0) ? (cSize.w / cSize.h) : 2.0;
  if (aspect >= 0.95) {
    return { NW: PW * 2 + GAP, NH: G.panelH, offs: [[0, 0], [PW + GAP, 0]] };
  }
  return { NW: PW, NH: G.panelH * 2, offs: [[0, 0], [0, G.panelH]] };
}

/* ---- render ---- */
function render(opts) {
  nnDraw.clear();
  var L = computeLayout();
  nnDraw.viewbox(0, 0, L.NW, L.NH);
  var bg = nnDraw.rect(L.NW, L.NH).fill('#ffffff');
  bg.on('click', function () {
    if (nnState.selected !== null) { nnState.selected = null; hidePopup(); render(); }
  });

  var paramEls = drawPanel(nnDraw, L.offs[0][0], L.offs[0][1], true, 'a)');
  drawPanel(nnDraw, L.offs[1][0], L.offs[1][1], false, 'b)');

  if (opts && opts.pulse) {
    paramEls.forEach(function (el) {
      el.attr('opacity', 0.06);
      el.animate(750).attr({ opacity: 1 });
    });
  }
}

document.addEventListener('fig-resize', function (e) {
  cSize.w = e.detail.width || cSize.w;
  cSize.h = e.detail.height || cSize.h;
  render();
});

/* ---- controls ---- */
function toggle_labelView(on) { nnState.labeled = !!on; render(); }
function update_hiddenCount(v) {
  nnState.D = v;
  if (nnState.selected !== null && nnState.selected >= v) nnState.selected = null;
  render();
}
function trigger_clearSelection() { nnState.selected = null; hidePopup(); render(); }

/* ---- demo steps ---- */
var nnSteps = [
  { title: 'The bare network',
    narr: 'One input x fans out to three hidden units, which all feed a single output y. Panel b (right) is that bare architecture; panel a (left) is the identical network with every parameter named.',
    st: { labeled: true, D: 3, sel: null }, pulse: false },
  { title: 'Name every parameter',
    narr: 'The labeled panel adds two orange bias nodes and every weight name: \u03B8i0 and \u03B8i1 on the input side, \u03D50 and \u03D5i on the output side. Untick \u201CFully labeled\u201D to see that the topology is unchanged.',
    st: { labeled: true, D: 3, sel: null }, pulse: true },
  { title: 'Follow one hidden unit',
    narr: 'h2 is highlighted: its incoming pair \u03B820 (bias) and \u03B821 (slope from x) form the pre-activation, the teal kink applies the ReLU, and \u03D52 scales its contribution to y. Click any other hi to trace it.',
    st: { labeled: true, D: 3, sel: 1 }, pulse: false },
  { title: 'Grow the hidden layer',
    narr: 'With D = 6 each new unit brings its own \u03B8i0, \u03B8i1 and \u03D5i, so the parameter count grows as 3D + 1 while the input and output stay single nodes.',
    st: { labeled: true, D: 6, sel: null }, pulse: false },
  { title: 'Shrink to one unit',
    narr: 'With D = 1 the network collapses to a single kinked line: y = \u03D50 + \u03D51\u00B7a[\u03B810 + \u03B811 x]. Everything richer is just a sum of more such pieces.',
    st: { labeled: true, D: 1, sel: null }, pulse: false }
];
var nnStep = 0;

function applyStep(i) {
  nnStep = (i % nnSteps.length + nnSteps.length) % nnSteps.length;
  var s = nnSteps[nnStep];
  nnState.labeled = s.st.labeled;
  nnState.D = s.st.D;
  nnState.selected = s.st.sel;
  document.getElementById('labelViewInput').checked = nnState.labeled;
  document.getElementById('hiddenCountInput').value = nnState.D;
  document.getElementById('hiddenCountVal').value = nnState.D;
  document.getElementById('demoNarration').innerHTML = '<strong>' + s.title + '.</strong> ' + s.narr;
  document.getElementById('stepLabel').textContent = 'Step ' + (nnStep + 1) + ' / ' + nnSteps.length;
  hidePopup();
  render({ pulse: s.pulse });
}
function nextStep() { applyStep(nnStep + 1); }
function prevStep() { applyStep(nnStep - 1); }

applyStep(0);
window.__markRendered();
